package sandbox

import (
	"context"
	"encoding/base64"
	"errors"
	"fmt"
	"mime"
	"path"
	"ragflow/internal/common"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/google/uuid"
	ucloudsdk "github.com/ucloud/ucloud-sandbox-sdk-go"
)

const (
	ucloudAgentSandboxDefaultRegion          = "cn-wlcb"
	ucloudAgentSandboxDomainSuffix           = "sandbox.ucloudai.com"
	ucloudAgentSandboxDefaultTemplate        = "base"
	ucloudAgentSandboxHome                   = "/home/user"
	ucloudAgentSandboxMaxArtifactDepth       = 16
	ucloudAgentSandboxDefaultTimeout         = 30
	ucloudAgentSandboxDefaultLifetime        = 300
	ucloudAgentSandboxDefaultMaxOutputBytes  = 1024 * 1024
	ucloudAgentSandboxDefaultMaxArtifacts    = 20
	ucloudAgentSandboxDefaultMaxArtifactSize = 10 * 1024 * 1024
)

type ucloudAgentSandboxInstance struct {
	sandbox       *ucloudsdk.Sandbox
	remoteWorkDir string
}

// UCloudAgentSandboxProvider executes code in disposable UCloud Agent Sandboxes.
type UCloudAgentSandboxProvider struct {
	client              *ucloudsdk.Client
	apiKey              string
	region              string
	domain              string
	apiURL              string
	template            string
	allowInternetAccess bool
	insecureHTTP        bool
	timeoutSec          int
	sandboxTimeoutSec   int
	maxOutputBytes      int
	maxArtifacts        int
	maxArtifactBytes    int

	mu          sync.RWMutex
	initialized bool
	instances   map[string]*ucloudAgentSandboxInstance
}

func newUCloudAgentSandboxProviderFromEnv() *UCloudAgentSandboxProvider {
	return newUCloudAgentSandboxProviderFromConfig(ucloudAgentSandboxConfigFromEnv())
}

func ucloudAgentSandboxConfigFromEnv() map[string]any {
	return map[string]any{
		"api_key":               common.GetEnv(common.EnvUCloudSandboxAPIKey),
		"region":                common.GetEnv(common.EnvUCloudSandboxRegion),
		"domain":                common.GetEnv(common.EnvUCloudSandboxDomain),
		"api_url":               common.GetEnv(common.EnvUCloudSandboxAPIURL),
		"template":              common.GetEnv(common.EnvUCloudSandboxTemplate),
		"allow_internet_access": common.GetEnv(common.EnvUCloudSandboxAllowInternetAccess),
		"insecure_http":         common.GetEnv(common.EnvUCloudSandboxInsecureHTTP),
		"timeout":               common.GetEnv(common.EnvUCloudSandboxExecutionTimeout),
		"sandbox_timeout":       common.GetEnv(common.EnvUCloudSandboxTimeout),
		"max_output_bytes":      common.GetEnv(common.EnvUCloudSandboxMaxOutputBytes),
		"max_artifacts":         common.GetEnv(common.EnvUCloudSandboxMaxArtifacts),
		"max_artifact_bytes":    common.GetEnv(common.EnvUCloudSandboxMaxArtifactBytes),
	}
}

func newUCloudAgentSandboxProviderFromConfig(cfg map[string]any) *UCloudAgentSandboxProvider {
	region := strings.TrimSpace(configString(cfg, "region"))
	if region == "" {
		region = ucloudAgentSandboxDefaultRegion
	}
	template := strings.TrimSpace(configString(cfg, "template"))
	if template == "" {
		template = ucloudAgentSandboxDefaultTemplate
	}
	return &UCloudAgentSandboxProvider{
		apiKey:              strings.TrimSpace(configString(cfg, "api_key")),
		region:              region,
		domain:              strings.TrimSpace(configString(cfg, "domain")),
		apiURL:              strings.TrimSpace(configString(cfg, "api_url")),
		template:            template,
		allowInternetAccess: strings.EqualFold(configString(cfg, "allow_internet_access"), "true"),
		insecureHTTP:        strings.EqualFold(configString(cfg, "insecure_http"), "true"),
		timeoutSec:          configInt(cfg, "timeout", ucloudAgentSandboxDefaultTimeout),
		sandboxTimeoutSec:   configInt(cfg, "sandbox_timeout", ucloudAgentSandboxDefaultLifetime),
		maxOutputBytes:      configInt(cfg, "max_output_bytes", ucloudAgentSandboxDefaultMaxOutputBytes),
		maxArtifacts:        configInt(cfg, "max_artifacts", ucloudAgentSandboxDefaultMaxArtifacts),
		maxArtifactBytes:    configInt(cfg, "max_artifact_bytes", ucloudAgentSandboxDefaultMaxArtifactSize),
		instances:           make(map[string]*ucloudAgentSandboxInstance),
	}
}

// ProviderType returns ProviderUCloudAgentSandbox.
func (p *UCloudAgentSandboxProvider) ProviderType() ProviderType {
	return ProviderUCloudAgentSandbox
}

// Initialize creates the UCloud SDK client. Connectivity is verified by the
// admin connection test, which creates and executes in a temporary sandbox.
func (p *UCloudAgentSandboxProvider) Initialize(context.Context) error {
	if p.apiKey == "" {
		return errors.New("ucloud agent sandbox: API key is required")
	}
	if p.timeoutSec <= 0 || p.sandboxTimeoutSec <= 0 || p.maxOutputBytes <= 0 || p.maxArtifactBytes <= 0 || p.maxArtifacts < 0 {
		return errors.New("ucloud agent sandbox: timeout and size limits must be positive, and max_artifacts must be non-negative")
	}
	domain := p.domain
	if domain == "" {
		domain = p.region + "." + ucloudAgentSandboxDomainSuffix
	}
	options := []ucloudsdk.ClientOption{
		ucloudsdk.WithRequestTimeout(time.Duration(p.timeoutSec) * time.Second),
		ucloudsdk.WithInsecureHTTP(p.insecureHTTP),
		// The SDK currently defaults to skipping TLS verification. RAGFlow
		// always opts into certificate verification.
		ucloudsdk.WithInsecureSkipTLS(false),
	}
	if p.apiURL != "" {
		options = append(options, ucloudsdk.WithAPIURL(p.apiURL))
	}
	p.client = ucloudsdk.NewClient(domain, p.apiKey, options...)
	p.mu.Lock()
	p.initialized = true
	p.mu.Unlock()
	return nil
}

// SupportedLanguages returns the runtimes included in UCloud's base template.
func (p *UCloudAgentSandboxProvider) SupportedLanguages() []string {
	return []string{"python", "javascript"}
}

// CreateInstance provisions a fresh UCloud Agent Sandbox.
func (p *UCloudAgentSandboxProvider) CreateInstance(ctx context.Context, template string) (*SandboxInstance, error) {
	if !p.isInitialized() {
		return nil, errors.New("ucloud agent sandbox: provider not initialized")
	}
	language := normalizeLanguage(template)
	if language == "" {
		return nil, fmt.Errorf("ucloud agent sandbox: unsupported language %q", template)
	}
	sbx, err := p.client.CreateSandbox(ctx,
		ucloudsdk.WithTemplate(p.template),
		ucloudsdk.WithTimeout(p.sandboxTimeoutSec),
		ucloudsdk.WithMetadata(map[string]string{"source": "ragflow"}),
		ucloudsdk.WithManageBy("ragflow"),
		ucloudsdk.WithSecure(true),
		ucloudsdk.WithAllowInternetAccess(p.allowInternetAccess),
	)
	if err != nil {
		return nil, fmt.Errorf("ucloud agent sandbox: create sandbox: %w", err)
	}
	remoteWorkDir := path.Join(ucloudAgentSandboxHome, "ragflow-codeexec-"+uuid.NewString())
	if _, err := sbx.Commands.Run(ctx, "mkdir -p "+shq(path.Join(remoteWorkDir, "artifacts")), ucloudsdk.WithCommandTimeout(minTimeout(p.timeoutSec, 10))); err != nil {
		_, _ = sbx.Kill(ctx)
		return nil, fmt.Errorf("ucloud agent sandbox: create workspace: %w", err)
	}
	p.mu.Lock()
	p.instances[sbx.ID] = &ucloudAgentSandboxInstance{sandbox: sbx, remoteWorkDir: remoteWorkDir}
	p.mu.Unlock()
	return &SandboxInstance{
		InstanceID: sbx.ID,
		Provider:   ProviderUCloudAgentSandbox,
		Status:     "running",
		Metadata: map[string]any{
			"language":        language,
			"remote_work_dir": remoteWorkDir,
			"sandbox_id":      sbx.ID,
			"template":        p.template,
		},
	}, nil
}

// ExecuteCode writes the shared RAGFlow wrapper into the sandbox and runs it.
func (p *UCloudAgentSandboxProvider) ExecuteCode(
	ctx context.Context,
	inst *SandboxInstance,
	code, language string,
	timeoutSec int,
	args map[string]any,
) (*ExecutionResult, error) {
	if !p.isInitialized() {
		return nil, errors.New("ucloud agent sandbox: provider not initialized")
	}
	if inst == nil || inst.InstanceID == "" {
		return nil, errors.New("ucloud agent sandbox: instance id required")
	}
	p.mu.RLock()
	instance := p.instances[inst.InstanceID]
	p.mu.RUnlock()
	if instance == nil {
		return nil, fmt.Errorf("ucloud agent sandbox: unknown instance %q", inst.InstanceID)
	}
	normalizedLanguage := normalizeLanguage(language)
	if normalizedLanguage == "" {
		return nil, fmt.Errorf("ucloud agent sandbox: unsupported language %q", language)
	}
	executionTimeout, err := validateTimeout(timeoutSec)
	if err != nil {
		return nil, err
	}
	if executionTimeout == 0 || executionTimeout > p.timeoutSec {
		executionTimeout = p.timeoutSec
	}
	argsJSON, err := argsToJSON(args)
	if err != nil {
		return nil, err
	}

	var scriptName, scriptContent, executable string
	if normalizedLanguage == "python" {
		scriptName = "main.py"
		scriptContent = BuildPythonWrapper(code, argsJSON)
		executable = "python3"
	} else {
		scriptName = "main.js"
		scriptContent = BuildJavaScriptWrapper(code, argsJSON)
		executable = "node"
	}
	scriptPath := path.Join(instance.remoteWorkDir, scriptName)
	if _, err := instance.sandbox.Files.Write(ctx, scriptPath, scriptContent); err != nil {
		return nil, fmt.Errorf("ucloud agent sandbox: write script: %w", err)
	}
	if err := instance.sandbox.SetTimeout(ctx, max(p.sandboxTimeoutSec, executionTimeout+30)); err != nil {
		return nil, fmt.Errorf("ucloud agent sandbox: extend sandbox timeout: %w", err)
	}

	started := time.Now()
	commandResult, runErr := instance.sandbox.Commands.Run(
		ctx,
		executable+" "+shq(scriptPath),
		ucloudsdk.WithCwd(instance.remoteWorkDir),
		ucloudsdk.WithCommandTimeout(executionTimeout),
	)
	executionTime := time.Since(started).Seconds()
	if runErr != nil {
		var exitErr *ucloudsdk.CommandExitError
		if errors.As(runErr, &exitErr) {
			commandResult = &ucloudsdk.CommandResult{Stdout: exitErr.Stdout, Stderr: exitErr.Stderr, ExitCode: exitErr.ExitCode, Error: exitErr.Message}
		} else {
			var timeoutErr *ucloudsdk.TimeoutError
			if errors.As(runErr, &timeoutErr) || errors.Is(runErr, context.DeadlineExceeded) {
				return nil, fmt.Errorf("ucloud agent sandbox: execution timed out after %d seconds: %w", executionTimeout, runErr)
			}
			return nil, fmt.Errorf("ucloud agent sandbox: execute code: %w", runErr)
		}
	}
	if commandResult == nil {
		return nil, errors.New("ucloud agent sandbox: command returned no result")
	}
	if len(commandResult.Stdout)+len(commandResult.Stderr) > p.maxOutputBytes {
		return nil, fmt.Errorf("ucloud agent sandbox: execution output exceeded %d bytes", p.maxOutputBytes)
	}
	stdout, structured := ExtractStructuredResult(commandResult.Stdout)
	artifacts := make([]map[string]any, 0)
	if err := p.collectArtifacts(ctx, instance.sandbox, path.Join(instance.remoteWorkDir, "artifacts"), "", &artifacts, 0); err != nil {
		return nil, err
	}
	return &ExecutionResult{
		Stdout:        stdout,
		Stderr:        commandResult.Stderr,
		ExitCode:      commandResult.ExitCode,
		ExecutionTime: executionTime,
		Metadata: map[string]any{
			"instance_id":       inst.InstanceID,
			"sandbox_id":        instance.sandbox.ID,
			"language":          normalizedLanguage,
			"script_path":       scriptPath,
			"remote_work_dir":   instance.remoteWorkDir,
			"status":            map[bool]string{true: "ok", false: "error"}[commandResult.ExitCode == 0],
			"timeout":           executionTimeout,
			"artifacts":         artifacts,
			"structured_result": structured,
		},
	}, nil
}

// DestroyInstance terminates the sandbox. A missing instance is already clean.
func (p *UCloudAgentSandboxProvider) DestroyInstance(ctx context.Context, inst *SandboxInstance) error {
	if !p.isInitialized() {
		return errors.New("ucloud agent sandbox: provider not initialized")
	}
	if inst == nil || inst.InstanceID == "" {
		return errors.New("ucloud agent sandbox: instance id required")
	}
	p.mu.Lock()
	instance := p.instances[inst.InstanceID]
	delete(p.instances, inst.InstanceID)
	p.mu.Unlock()
	if instance == nil {
		return nil
	}
	if _, err := instance.sandbox.Kill(ctx); err != nil {
		return fmt.Errorf("ucloud agent sandbox: kill sandbox: %w", err)
	}
	return nil
}

// HealthCheck reports whether the provider has a configured client.
func (p *UCloudAgentSandboxProvider) HealthCheck(context.Context) error {
	if !p.isInitialized() || p.client == nil {
		return errors.New("ucloud agent sandbox: provider not initialized")
	}
	return nil
}

func (p *UCloudAgentSandboxProvider) collectArtifacts(
	ctx context.Context,
	sbx *ucloudsdk.Sandbox,
	currentDir, relativeDir string,
	artifacts *[]map[string]any,
	depth int,
) error {
	if depth > ucloudAgentSandboxMaxArtifactDepth {
		return fmt.Errorf("ucloud agent sandbox: artifact directory nesting exceeds %d levels: %s", ucloudAgentSandboxMaxArtifactDepth, relativeDir)
	}
	entries, err := sbx.Files.List(ctx, currentDir, ucloudsdk.WithDepth(1))
	if err != nil {
		if errors.Is(err, ucloudsdk.ErrNotFound) {
			return nil
		}
		return fmt.Errorf("ucloud agent sandbox: list artifacts: %w", err)
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Path < entries[j].Path })
	for _, entry := range entries {
		name := path.Base(entry.Path)
		relativePath := path.Join(relativeDir, name)
		if entry.SymlinkTarget != nil {
			return fmt.Errorf("ucloud agent sandbox: artifact symlinks are not allowed: %s", relativePath)
		}
		if entry.Type == ucloudsdk.EntryTypeDir {
			if err := p.collectArtifacts(ctx, sbx, entry.Path, relativePath, artifacts, depth+1); err != nil {
				return err
			}
			continue
		}
		if len(*artifacts) >= p.maxArtifacts {
			return fmt.Errorf("ucloud agent sandbox: execution produced more than %d artifacts", p.maxArtifacts)
		}
		if entry.Size > int64(p.maxArtifactBytes) {
			return fmt.Errorf("ucloud agent sandbox: artifact exceeds %d bytes: %s", p.maxArtifactBytes, relativePath)
		}
		extension := strings.ToLower(path.Ext(name))
		if _, allowed := allowedArtifactExts[extension]; !allowed {
			return fmt.Errorf("ucloud agent sandbox: unsupported artifact type: %s", relativePath)
		}
		content, err := sbx.Files.ReadBytes(ctx, entry.Path)
		if err != nil {
			return fmt.Errorf("ucloud agent sandbox: read artifact %s: %w", relativePath, err)
		}
		mimeType := mime.TypeByExtension(extension)
		if mimeType == "" {
			mimeType = "application/octet-stream"
		}
		*artifacts = append(*artifacts, map[string]any{
			"name":        relativePath,
			"content_b64": base64.StdEncoding.EncodeToString(content),
			"mime_type":   mimeType,
			"size":        entry.Size,
		})
	}
	return nil
}

func (p *UCloudAgentSandboxProvider) isInitialized() bool {
	p.mu.RLock()
	defer p.mu.RUnlock()
	return p.initialized
}

// Package agentcore provides graph-based workflow agents (Sequential, Parallel,
// Loop) using the project's own StateGraph/Pregel engine.
//
// Unlike the legacy workflow.go implementation, these graph-based workflows:
//   - Auto-checkpoint at each sub-agent boundary (via graph.WithCheckpointer)
//   - Support interrupt/resume at any sub-agent (via graph.WithInterrupts)
//   - Emit streaming events through the Pregel StreamManager
//   - Use the Pregel engine's recursion limit and cancellation support
//
// Usage:
//
//	gwf, err := NewSequentialGraph(ctx, &SequentialConfig{...}, checkpointer)
//	state, err := gwf.Invoke(ctx, input)
package core

import (
	"context"
	"fmt"
	"sync"

	"ragflow/internal/harness/core/schema"
	"ragflow/internal/harness/graph/checkpoint"
	"ragflow/internal/harness/graph/constants"
	"ragflow/internal/harness/graph/graph"
	"ragflow/internal/harness/graph/types"
)

func init() {
	schema.RegisterType("_harness_wf_graph_state", func() any { return &WorkflowGraphState{} })
}

// WorkflowGraphState is the shared state for graph-based workflow agents.
// It carries messages between sub-agents and tracks the current position.
type WorkflowGraphState struct {
	Messages      []*schema.Message
	SubAgentNames []string // names of sub-agents in order
	CurrentStep   int      // current sub-agent index
	LoopIter      int      // for loop mode
	MaxLoopIter   int      // for loop mode
	Done          bool

	mu sync.Mutex // protects Messages from concurrent access in inline execution
}

// AppendMessage safely appends a message to the Messages slice.
func (s *WorkflowGraphState) AppendMessage(msg *schema.Message) {
	s.mu.Lock()
	s.Messages = append(s.Messages, msg)
	s.mu.Unlock()
}

// SnapshotMessages safely returns a copy of the Messages slice.
func (s *WorkflowGraphState) SnapshotMessages() []*schema.Message {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]*schema.Message(nil), s.Messages...)
}

// MessagesLen safely returns the length of Messages.
func (s *WorkflowGraphState) MessagesLen() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.Messages)
}

// WorkflowGraph wraps a CompiledGraph that runs sub-agents as graph nodes.
type WorkflowGraph struct {
	compiled types.CompiledGraph
}

// ---- Sequential ----

// NewSequentialGraph builds a StateGraph where sub-agents run sequentially.
//
//	start → sub_0 → sub_1 → ... → sub_n → end
//
// Each sub-agent boundary is a checkpoint point. Interrupt can be enabled
// before any sub-agent via WithInterrupts.
func NewSequentialGraph(ctx context.Context, cfg *SequentialConfig, cptr checkpoint.BaseCheckpointer, interrupts ...string) (*WorkflowGraph, error) {
	if cfg == nil {
		return nil, fmt.Errorf("SequentialConfig is nil")
	}
	if len(cfg.SubAgents) == 0 {
		return nil, fmt.Errorf("SequentialConfig requires at least one sub-agent")
	}
	sg := graph.NewStateGraph(&WorkflowGraphState{})

	names := make([]string, len(cfg.SubAgents))
	for i, a := range cfg.SubAgents {
		names[i] = a.Name(ctx)
	}

	// Create one node per sub-agent.
	for i, agent := range cfg.SubAgents {
		idx := i
		ag := agent // capture
		nodeName := fmt.Sprintf("sub_%d", i)
		sg.AddNode(nodeName, func(ctx context.Context, state interface{}) (interface{}, error) {
			s := state.(*WorkflowGraphState)
			// Copy Messages slice so the sub-agent's goroutine doesn't share
			// the underlying array with the graph's concurrent goroutines.
			msgCopy := append([]*schema.Message(nil), s.Messages...)
			iter := ag.Run(ctx, &AgentInput{Messages: msgCopy})
			s.Messages = nil // Return only new messages to the append channel.
			for {
				ev, ok := iter.Next()
				if !ok {
					break
				}
				if ev.Err != nil {
					return nil, fmt.Errorf("sub-agent %s: %w", names[idx], ev.Err)
				}
				if ev.Output != nil && ev.Output.MessageOutput != nil &&
					!ev.Output.MessageOutput.IsStreaming &&
					ev.Output.MessageOutput.Message != nil {
					s.AppendMessage(ev.Output.MessageOutput.Message)
				}
			}
			s.CurrentStep = idx + 1
			return s, nil
		})
	}

	// Chain nodes sequentially.
	sg.AddEdge(constants.Start, "sub_0")
	for i := 1; i < len(cfg.SubAgents); i++ {
		sg.AddEdge(fmt.Sprintf("sub_%d", i-1), fmt.Sprintf("sub_%d", i))
	}
	sg.AddEdge(fmt.Sprintf("sub_%d", len(cfg.SubAgents)-1), constants.End)

	compileOpts := []interface{}{
		graph.WithRecursionLimit(len(cfg.SubAgents)*10 + 5),
	}
	if cptr != nil {
		compileOpts = append(compileOpts, graph.WithCheckpointer(cptr))
	}
	for _, name := range interrupts {
		compileOpts = append(compileOpts, graph.WithInterrupts(name))
	}

	compiled, err := sg.Compile(compileOpts...)
	if err != nil {
		return nil, fmt.Errorf("compile sequential graph: %w", err)
	}

	return &WorkflowGraph{compiled: compiled}, nil
}

// ---- Parallel ----

// NewParallelGraph builds a StateGraph where sub-agents run in parallel via
// a split node that fans out to all sub-agents.
//
//	start → __wf_split__ ─┬→ sub_0 ─┬→ end
//	                      ├→ sub_1 ─┤
//	                      └→ sub_n ─┘
func NewParallelGraph(ctx context.Context, cfg *ParallelConfig, cptr checkpoint.BaseCheckpointer, interrupts ...string) (*WorkflowGraph, error) {
	if cfg == nil {
		return nil, fmt.Errorf("ParallelConfig is nil")
	}
	if len(cfg.SubAgents) == 0 {
		return nil, fmt.Errorf("ParallelConfig requires at least one sub-agent")
	}
	sg := graph.NewStateGraph(&WorkflowGraphState{})

	names := make([]string, len(cfg.SubAgents))
	for i, a := range cfg.SubAgents {
		names[i] = a.Name(ctx)
	}

	// Add a split node that fans out to all sub-agents via multiple outgoing edges.
	sg.AddNode("__wf_split__", func(ctx context.Context, state interface{}) (interface{}, error) {
		return state, nil
	})
	sg.AddEdge(constants.Start, "__wf_split__")

	// Each sub-agent is a node that appends its output.
	for i, agent := range cfg.SubAgents {
		idx := i
		ag := agent
		nodeName := fmt.Sprintf("sub_%d", i)
		sg.AddNode(nodeName, func(ctx context.Context, state interface{}) (interface{}, error) {
			s := state.(*WorkflowGraphState)
			msgCopy := s.SnapshotMessages()
			iter := ag.Run(ctx, &AgentInput{Messages: msgCopy})
			s.Messages = nil // Return only new messages to the append channel.
			for {
				ev, ok := iter.Next()
				if !ok {
					break
				}
				if ev.Err != nil {
					return nil, fmt.Errorf("sub-agent %s: %w", names[idx], ev.Err)
				}
				if ev.Output != nil && ev.Output.MessageOutput != nil &&
					!ev.Output.MessageOutput.IsStreaming &&
					ev.Output.MessageOutput.Message != nil {
					s.AppendMessage(ev.Output.MessageOutput.Message)
				}
			}
			return map[string]interface{}{
				"Messages": s.SnapshotMessages(),
			}, nil
		})
		sg.AddEdge("__wf_split__", nodeName)
		sg.AddEdge(nodeName, constants.End)
	}

	compileOpts := []interface{}{
		graph.WithRecursionLimit(len(cfg.SubAgents)*10 + 5),
	}
	if cptr != nil {
		compileOpts = append(compileOpts, graph.WithCheckpointer(cptr))
	}
	for _, name := range interrupts {
		compileOpts = append(compileOpts, graph.WithInterrupts(name))
	}

	compiled, err := sg.Compile(compileOpts...)
	if err != nil {
		return nil, fmt.Errorf("compile parallel graph: %w", err)
	}

	return &WorkflowGraph{compiled: compiled}, nil
}

// ---- Loop ----

// NewLoopGraph builds a StateGraph that runs sub-agents in a loop with bounded
// iterations.
//
//	start → sub_0 → sub_1 → ... → sub_n → [iter < max?] → back to sub_0
//	                                        ↘ end
func NewLoopGraph(ctx context.Context, cfg *LoopConfig, cptr checkpoint.BaseCheckpointer, interrupts ...string) (*WorkflowGraph, error) {
	if cfg == nil {
		return nil, fmt.Errorf("LoopConfig is nil")
	}
	if len(cfg.SubAgents) == 0 {
		return nil, fmt.Errorf("LoopConfig requires at least one sub-agent")
	}
	sg := graph.NewStateGraph(&WorkflowGraphState{})

	maxIter := cfg.MaxIterations
	if maxIter <= 0 {
		maxIter = 10
	}

	names := make([]string, len(cfg.SubAgents))
	for i, a := range cfg.SubAgents {
		names[i] = a.Name(ctx)
	}

	// One node per sub-agent.
	for i, agent := range cfg.SubAgents {
		idx := i
		ag := agent
		nodeName := fmt.Sprintf("sub_%d", i)
		sg.AddNode(nodeName, func(ctx context.Context, state interface{}) (interface{}, error) {
			s := state.(*WorkflowGraphState)
			// Copy Messages slice so the sub-agent's goroutine doesn't share
			// the underlying array with the graph's concurrent goroutines.
			msgCopy := append([]*schema.Message(nil), s.Messages...)
			iter := ag.Run(ctx, &AgentInput{Messages: msgCopy})
			s.Messages = nil // Return only new messages to the append channel.
			for {
				ev, ok := iter.Next()
				if !ok {
					break
				}
				if ev.Err != nil {
					return nil, fmt.Errorf("sub-agent %s: %w", names[idx], ev.Err)
				}
				if ev.Output != nil && ev.Output.MessageOutput != nil &&
					!ev.Output.MessageOutput.IsStreaming &&
					ev.Output.MessageOutput.Message != nil {
					s.AppendMessage(ev.Output.MessageOutput.Message)
				}
			}
			s.CurrentStep = idx + 1
			// Increment LoopIter in the last node so it persists to channels.
			// (The conditional edge only reads LoopIter for routing.)
			if idx == len(cfg.SubAgents)-1 {
				s.LoopIter++
			}
			return s, nil
		})
	}

	// Chain: start → sub_0 → sub_1 → ... → sub_n
	sg.AddEdge(constants.Start, "sub_0")
	for i := 1; i < len(cfg.SubAgents); i++ {
		sg.AddEdge(fmt.Sprintf("sub_%d", i-1), fmt.Sprintf("sub_%d", i))
	}

	// Conditional edge from last sub-agent: loop back or end.
	lastNode := fmt.Sprintf("sub_%d", len(cfg.SubAgents)-1)
	sg.AddConditionalEdges(lastNode,
		func(ctx context.Context, state interface{}) (interface{}, error) {
			s := state.(*WorkflowGraphState)
			if s.LoopIter >= maxIter {
				s.Done = true
				return constants.End, nil
			}
			return "sub_0", nil
		},
		map[string]string{
			constants.End: constants.End,
			"sub_0":       "sub_0",
		},
	)
	// Mark lastNode as a finish point so graph validation passes. The
	// conditional edge to End is the actual runtime termination path.
	sg.SetFinishPoint(lastNode)

	// Use a generous recursion limit. The sub-agent execution within each
	// loop iteration can consume multiple steps internally; the parent graph
	// recursion limit must account for this.
	recLimit := maxIter*len(cfg.SubAgents)*50 + 50
	compileOpts := []interface{}{
		graph.WithRecursionLimit(recLimit),
	}
	if cptr != nil {
		compileOpts = append(compileOpts, graph.WithCheckpointer(cptr))
	}
	for _, name := range interrupts {
		compileOpts = append(compileOpts, graph.WithInterrupts(name))
	}

	compiled, err := sg.Compile(compileOpts...)
	if err != nil {
		return nil, fmt.Errorf("compile loop graph: %w", err)
	}

	return &WorkflowGraph{compiled: compiled}, nil
}

// ---- Invocation ----

// toWorkflowGraphState converts the engine's result (map or typed struct)
// back to *WorkflowGraphState. The Pregel engine serializes state through
// channels which may flatten structs into map[string]interface{}.
func toWorkflowGraphState(result interface{}) (*WorkflowGraphState, error) {
	switch v := result.(type) {
	case *WorkflowGraphState:
		return v, nil
	case map[string]interface{}:
		return mapToWorkflowGraphState(v)
	default:
		return nil, fmt.Errorf("unexpected result type %T from workflow graph", result)
	}
}

// mapToWorkflowGraphState converts a map result to WorkflowGraphState.
// The Pregel engine uses Go struct field names as channel keys (PascalCase).
func mapToWorkflowGraphState(m map[string]interface{}) (*WorkflowGraphState, error) {
	s := &WorkflowGraphState{}
	if msgs, ok := m["Messages"]; ok {
		if msgList, ok := msgs.([]*schema.Message); ok {
			s.Messages = msgList
		} else if rawList, ok := msgs.([]interface{}); ok {
			for _, raw := range rawList {
				if msg, ok := raw.(*schema.Message); ok {
					s.Messages = append(s.Messages, msg)
				}
			}
		}
	}
	if step, ok := m["CurrentStep"].(int); ok {
		s.CurrentStep = step
	} else if step, ok := m["CurrentStep"].(float64); ok {
		s.CurrentStep = int(step)
	}
	if iter, ok := m["LoopIter"].(int); ok {
		s.LoopIter = iter
	} else if iter, ok := m["LoopIter"].(float64); ok {
		s.LoopIter = int(iter)
	}
	if maxIter, ok := m["MaxLoopIter"].(int); ok {
		s.MaxLoopIter = maxIter
	} else if maxIter, ok := m["MaxLoopIter"].(float64); ok {
		s.MaxLoopIter = int(maxIter)
	}
	if done, ok := m["Done"].(bool); ok {
		s.Done = done
	}
	return s, nil
}

// Invoke runs the workflow graph synchronously and returns the final state.
func (wg *WorkflowGraph) Invoke(ctx context.Context, input *AgentInput) (*WorkflowGraphState, error) {
	if wg == nil || wg.compiled == nil {
		return nil, fmt.Errorf("workflow graph is not compiled")
	}
	if input == nil {
		input = &AgentInput{}
	}
	state := &WorkflowGraphState{
		Messages:    input.Messages,
		CurrentStep: 0,
	}
	result, err := wg.compiled.Invoke(ctx, state)
	if err != nil {
		return nil, err
	}
	return toWorkflowGraphState(result)
}

// Stream runs the workflow graph with streaming events via Pregel.
func (wg *WorkflowGraph) Stream(ctx context.Context, input *AgentInput, mode types.StreamMode) (<-chan interface{}, <-chan error) {
	if input == nil {
		input = &AgentInput{}
	}
	state := &WorkflowGraphState{
		Messages:    input.Messages,
		CurrentStep: 0,
	}
	return wg.compiled.Stream(ctx, state, mode)
}

// Resume resumes a previously interrupted workflow.
// Resume resumes a previously interrupted workflow graph from its checkpoint.
// Note: this is a thin wrapper that invokes the compiled graph with an empty state.
// For proper checkpoint resume, ensure the compiled graph was configured with a
// checkpointer and the config has the correct ThreadID for checkpoint lookup.
func (wg *WorkflowGraph) Resume(ctx context.Context) (*WorkflowGraphState, error) {
	result, err := wg.compiled.Invoke(ctx, &WorkflowGraphState{})
	if err != nil {
		return nil, err
	}
	return toWorkflowGraphState(result)
}

// Compile returns the underlying CompiledGraph.
func (wg *WorkflowGraph) Compile() types.CompiledGraph { return wg.compiled }

